import{_ as a,I as o,g as t,j as r}from"./chunks/framework.CjoWWfVe.js";const m=JSON.parse('{"title":"Marketplace (Add-ons)","description":"Connect extensions, customize the program for your specific craft, and manage modules.","frontmatter":{"title":"Marketplace (Add-ons)","description":"Connect extensions, customize the program for your specific craft, and manage modules.","order":16},"headers":[],"relativePath":"docs/spaces/marketplace.md","filePath":"docs/spaces/marketplace.md"}'),s={name:"docs/spaces/marketplace.md"};function n(l,e,i,c,u,d){return o(),t("div",null,[...e[0]||(e[0]=[r('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation is under development</p><p><strong>Dear users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, being regularly improved and expanded, the reference materials are also updated gradually.</p><p>At the moment, please treat the documentation as indicative — it is incomplete, may temporarily lack descriptions of some features, or contain inaccuracies.</p></div><h1 id="🧩-marketplace-ecosystem-of-extensions" tabindex="-1">🧩 Marketplace (Ecosystem of Extensions) <a class="header-anchor" href="#🧩-marketplace-ecosystem-of-extensions" aria-label="Permalink to &quot;🧩 Marketplace (Ecosystem of Extensions)&quot;">​</a></h1><p>The profession of a handcrafter is too multifaceted to fit into a single universal interface. What is ideal for a leathercrafter (patterns, cutting area) will be absolutely useless for a watch repairer or a potter, only overloading the program with unnecessary buttons.</p><p>To solve this problem, OmniCraft ERP uses an architecture of <strong>Global Modules (Add-ons)</strong>. The base core of the program remains light and fast, and you can connect specific niche functions yourself through the built-in <strong>Marketplace</strong>.</p><hr><h2 id="🛒-how-the-marketplace-works" tabindex="-1">🛒 How the Marketplace works <a class="header-anchor" href="#🛒-how-the-marketplace-works" aria-label="Permalink to &quot;🛒 How the Marketplace works&quot;">​</a></h2><p>In the right slide-out panel (Drawer) in the &quot;Extensions &amp; Marketplace&quot; section, there is a <strong>Marketplace</strong> button. When you click it, the program contacts the server and loads the current catalog of available extensions.</p><h3 id="_1-connecting-free-modules" tabindex="-1">1. Connecting Free Modules <a class="header-anchor" href="#_1-connecting-free-modules" aria-label="Permalink to &quot;1. Connecting Free Modules&quot;">​</a></h3><p>Some system modules (for example, <em>Ambassador</em>) are distributed absolutely free of charge. To start using them:</p><ol><li>Open the Marketplace.</li><li>Find the module you need and click <strong>Connect for free</strong>.</li><li>The program will instantly update your license key and unlock the module. No downloading files, installation, or program restarts are required — the module will immediately appear in the side menu!</li></ol><h3 id="_2-purchasing-paid-modules" tabindex="-1">2. Purchasing Paid Modules <a class="header-anchor" href="#_2-purchasing-paid-modules" aria-label="Permalink to &quot;2. Purchasing Paid Modules&quot;">​</a></h3><p>Highly specialized professional modules are paid as a one-time fee. You pay only for those instruments that you actually use in your work.</p><ol><li>In the paid module card, click <strong>Buy for X ₽</strong>.</li><li>A secure online payment window will open in your browser.</li><li>Immediately after a successful payment, the module will automatically link to your license key, and you can start working.</li></ol><div class="tip custom-block"><p class="custom-block-title">Technical Magic (Zero Overhead)</p><p>You don&#39;t need to worry that installing dozens of modules will slow down your computer. All modules are physically sewn into the program&#39;s source code, but they use a &quot;Lazy Loading&quot; architecture. The module does not consume a single megabyte of RAM until you click on it.</p></div><hr><h2 id="🔄-the-global-nature-of-modules" tabindex="-1">🔄 The Global Nature of Modules <a class="header-anchor" href="#🔄-the-global-nature-of-modules" aria-label="Permalink to &quot;🔄 The Global Nature of Modules&quot;">​</a></h2><p>Unlike material warehouses or receipts, which are strictly tied to a specific business (in PRO mode), global modules work <strong>on top of all your workspaces</strong>.</p><p>If you bought the &quot;Patterns&quot; module, you will be able to use a single database of your drawings and patterns regardless of which of your business workspaces you are currently in.</p>',18)])])}const h=a(s,[["render",n]]);export{m as __pageData,h as default};
